    t1_title: "Megújuló vs. Fosszilis",
    t1_text: "Az energiaátmenet célja a fosszilis tüzelőanyagok felváltása megújuló energiaforrásokkal. Ez segít a klímaváltozás mérséklésében.",
    t1_h1: "Tiszta energia",
