    t1_inst: "Párosítsd az energiaforrást a típusával.",
    t1_q: "Mi a globális energiaátmenet fő célja?",
    t1_qa: "Áttérés a fosszilis energiahordozókról a megújulókra.",
    t1_qb: "A globális szénkitermelés növelése.",
    t1_qc: "Az áramhasználat teljes beszüntetése.",
    t1_qd: "Több olajfinomító építése.",
