    t2_title: "Energiatárolás",
    t2_text: "Az ingadozó megújuló energiát tárolni kell a villamosenergia-hálózat stabilitása érdekében. Az akkumulátorok és a szivattyús tározók kulcsszerepet játszanak.",
    t2_h1: "Hálózati stabilitás",
    t2_h2: "Tárolási technológiák",
    t2_inst: "Kategorizáld a technológiákat.",
