    t4_title: "Globális energiakihívások",
    t4_text: "A különböző régiók egyedi kihívásokkal néznek szembe a tiszta energiára való átállás során. A fejlődő országoknak hatalmas beruházásokra van szükségük az infrastruktúrához.",
