    t12_title: "Műholdak és földrajz",
    t12_text: "A modern földrajz erősen támaszkodik a digitális műholdadatokra. A Földmegfigyelő műholdak nyomon követik a klímaváltozást, az erdőirtást és a városnövekedést.",
